import{_ as a,o as t,c as s,a2 as n}from"./chunks/framework.BZO4qERu.js";const g=JSON.parse('{"title":"Run your first search locally","description":"","frontmatter":{},"headers":[],"relativePath":"get-started/local.md","filePath":"get-started/local.md","lastUpdated":1793111003000}'),i={name:"get-started/local.md"};function o(r,e,l,h,p,d){return t(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="run-your-first-search-locally" tabindex="-1">Run your first search locally <a class="header-anchor" href="#run-your-first-search-locally" aria-label="Permalink to &quot;Run your first search locally&quot;">​</a></h1><p>Install PaperSeek on your own machine, connect a model, and turn a question into a reading list.</p><p>Prefer to skip installation? <a href="./online">Run your first search online</a> instead.</p><h2 id="_1-install" tabindex="-1">1. Install <a class="header-anchor" href="#_1-install" aria-label="Permalink to &quot;1. Install&quot;">​</a></h2><p>Use <strong>Python 3.12 or newer</strong> and an isolated environment.</p><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-EQbU9" id="tab-l75t1bn" checked><label data-title="macOS / Linux" for="tab-l75t1bn">macOS / Linux</label><input type="radio" name="group-EQbU9" id="tab-Qta0O1_"><label data-title="Windows PowerShell" for="tab-Qta0O1_">Windows PowerShell</label></div><div class="blocks"><div class="language-bash vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> venv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .venv</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .venv/bin/activate</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;paperseek==1.0.0b5&quot;</span></span></code></pre></div><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">py </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">-3.12</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">m venv .venv</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.\\.venv\\Scripts\\Activate.ps1</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">python </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">m pip install </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;paperseek==1.0.0b5&quot;</span></span></code></pre></div></div></div><p>For a 1.0.0-beta5 source checkout, use <code>python -m pip install ./backend</code> instead. After changing frontend source, follow the <a href="./../developers/contributing">contributor build instructions</a>.</p><h2 id="_2-start" tabindex="-1">2. Start <a class="header-anchor" href="#_2-start" aria-label="Permalink to &quot;2. Start&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">paperseek</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span></span></code></pre></div><p>Open <strong><a href="http://127.0.0.1:8765" target="_blank" rel="noreferrer">http://127.0.0.1:8765</a></strong>. Keep the terminal running while you use the local app.</p><p>The package includes the web interface; Node.js is not required to run it.</p><h2 id="_3-connect-a-model" tabindex="-1">3. Connect a model <a class="header-anchor" href="#_3-connect-a-model" aria-label="Permalink to &quot;3. Connect a model&quot;">​</a></h2><p>Open <strong>Settings → Model APIs</strong> at the bottom of the sidebar and choose <strong>Add connection</strong>. Select <strong>LLM</strong>, a provider and a model, then enter your key. For a custom service, check the base URL and protocol as well. You can use <strong>Test connection</strong> to check the model draft, then click <strong>Save</strong> to keep it. Under <strong>Defaults</strong>, select the saved connection for <strong>Search and scoring</strong>. Return through <strong>Search</strong> in the sidebar.</p><p>OpenAI Chat Completions, OpenAI Responses, and Anthropic Messages are distinct protocols. A model name alone does not identify the right one.</p><p>Model draft testing does not save the connection. Data-source testing has different save behavior, described below. To supply deployment defaults instead, see <a href="./../reference/configuration">configuration</a>.</p><h2 id="_4-ask-a-question" tabindex="-1">4. Ask a question <a class="header-anchor" href="#_4-ask-a-question" aria-label="Permalink to &quot;4. Ask a question&quot;">​</a></h2><blockquote><p>How does open-source software obtain funding for long-term maintenance?</p></blockquote><p>If you have an OpenAlex key, open <strong>Settings → Data sources → OpenAlex → Configure</strong>, enter it, and click <strong>Save</strong>. <strong>Test connection</strong> in this data-source dialog also saves the current key and options before testing; a failed test or subsequently cancelling the dialog does not undo the save.</p><p>Return to <strong>Search</strong> in the sidebar and choose <strong>OpenAlex</strong>. Only restrict the research field under <strong>More options</strong> when needed. Leave the budget on <strong>Auto</strong> for a first run, or choose a budget to match the breadth of your question.</p><p>Select <strong>Start search</strong>, or press <strong>Ctrl+Enter / ⌘+Enter</strong>. Follow the stages while PaperSeek searches and ranks.</p><h2 id="_5-read-the-results" tabindex="-1">5. Read the results <a class="header-anchor" href="#_5-read-the-results" aria-label="Permalink to &quot;5. Read the results&quot;">​</a></h2><p>Open <strong>Results</strong>, inspect abstracts and relevance explanations, and export CSV, JSON, BibTeX, or RIS. Community saves history locally.</p><p>Reopen a run from <strong>Search history</strong> in the sidebar, or click <strong>All</strong> beside that heading for the full list. Use <strong>Citation evidence</strong> to explore available citation data, or select papers for an <a href="./../guide/reviews">experimental review</a>. Open <a href="./../guide/bibliometrics">Bibliometrics</a> from the sidebar to analyze the full retrieved candidate corpus.</p><h2 id="if-something-fails" tabindex="-1">If something fails <a class="header-anchor" href="#if-something-fails" aria-label="Permalink to &quot;If something fails&quot;">​</a></h2><p>Start with <a href="./../reference/troubleshooting">troubleshooting</a>. For a local setup check:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">paperseek</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span></span></code></pre></div><p>A valid configuration does not guarantee available credit or uninterrupted upstream service throughout a long search.</p><h2 id="what-next" tabindex="-1">What next? <a class="header-anchor" href="#what-next" aria-label="Permalink to &quot;What next?&quot;">​</a></h2><ul><li><a href="./../self-hosting/">Self-hosting</a>: Docker deployment, data directories, network access, and backups.</li><li><a href="./../guide/search">Search the literature</a>: budgets, field filters, stopping and reconnecting.</li></ul>`,29)])])}const u=a(i,[["render",o]]);export{g as __pageData,u as default};
